def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Tally history once.
    my_c = 0
    op_c = 0
    for me, opp in history:
        if me == 'C':
            my_c += 1
        if opp == 'C':
            op_c += 1

    op_d = n - op_c
    my_d = n - my_c

    # Opponent cooperation over full match.
    rate = op_c / n

    # Opponent's very recent behavior.
    last_me, last_op = history[-1]
    op_last3 = [o for _, o in history[-3:]]
    op_last5 = [o for _, o in history[-5:]]
    recent_d3 = 3 - op_last3.count('C')
    recent_d5 = 5 - op_last5.count('C')

    # Immediate retaliation for an unprovoked defection.
    if last_op == 'D':
        # If opponent is overwhelmingly cooperative historically,
        # forgive once in a while rather than fall into DD.
        if rate >= 0.85 and op_d <= 2:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # Persistent defection pressure: stay in D.
        if recent_d3 == 3 or recent_d5 >= 4:
            return 'D'
        return 'D'

    # Opponent cooperated last round.
    # If we just defected and they forgave, mostly cooperate but probe occasionally.
    if last_me == 'D':
        if recent_d5 >= 3:
            # They are still fairly hostile; punish.
            return 'D'
        if rng.random() < 0.2:
            return 'D'
        return 'C'

    # Opponent fully cooperative so far.
    if op_d == 0:
        # Near the end, exploit a pure cooperator.
        if n >= 96:
            return 'D' if rng.random() < 0.6 else 'C'
        # Rare probing for free points against overly trusting opponents.
        if n >= 20 and n % 17 == 0 and rng.random() < 0.25:
            return 'D'
        return 'C'

    # Opponent occasionally defected but currently cooperative.
    if rate >= 0.7:
        # Mostly cooperate, small exploit chance late.
        if n >= 90 and rate >= 0.8 and rng.random() < 0.3:
            return 'D'
        return 'C'

    if rate >= 0.4:
        # Boundary: cooperate mostly, defect with low probability to avoid being exploited.
        if recent_d5 >= 2:
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        if rng.random() < 0.1:
            return 'D'
        return 'C'

    # Mostly defecting opponent: defect, with occasional cooperative probe.
    if rng.random() < 0.05:
        return 'C'
    return 'D'
